fn main() {
    // ---- String slices ----
    let s = String::from("Hello, world!");

    // Slice a portion of the string
    let hello = &s[0..5];  // "Hello"
    let world = &s[7..12];  // "world"
    let all = &s[..];  // "Hello, world!"
    let from_start = &s[..5];  // "Hello"
    let to_end = &s[7..];  // "world!"

    println!("hello: {}", hello);
    println!("world: {}", world);
    println!("all: {}", all);
    println!("from_start: {}", from_start);
    println!("to_end: {}", to_end);

    // ---- Array slices ----
    let arr = [1, 2, 3, 4, 5];
    let slice1 = &arr[1..4];  // [2, 3, 4]
    let slice2 = &arr[..];  // [1, 2, 3, 4, 5]

    println!("slice1: {:?}", slice1);
    println!("slice2: {:?}", slice2);

    // ---- Slices are references ----
    // They borrow data
    // They don't own the data
    // They cannot outlive the data they reference

    // ---- Function with slice parameter ----
    let s2 = String::from("Hello, world!");
    let word = first_word(&s2);
    println!("first word: {}", word);

    // ---- Slice with string literal ----
    let s3 = "Hello, world!";  // &str
    let word2 = first_word(s3);
    println!("first word: {}", word2);
}

fn first_word(s: &str) -> &str {
    let bytes = s.as_bytes();
    for (i, &item) in bytes.iter().enumerate() {
        if item == b' ' {
            return &s[0..i];
        }
    }
